WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) / 30 AS months_since_paid_at, CONCAT(method, ' ', status) AS method_status FROM payments WHERE amount BETWEEN 650 AND 1600) SELECT method, COUNT(*) AS cnt, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, PERCENTILE_APPROX(months_since_paid_at, ARRAY(0.25, 0.5, 0.75)) AS months_since_paid_at_quartiles, GROUPING(method) AS grouping_id FROM filtered GROUP BY CUBE (method) ORDER BY method DESC;
